def cooking_order(needs: dict[str, list[str]], dish: str) -> list[str]:
    done: set[str] = set()
    order: list[str] = []

    def visit(item: str) -> None:
        done.add(item)
        order.append(item)
        for part in needs.get(item, []):
            visit(part)

    visit(dish)
    return order
